  document.title=owner?'Gestão — Barbearia Modelo':staff?'Minha área — Barbearia Modelo':'Barbearia Modelo — Barbearia';
  if(!owner&&!staff){$('#website').hidden=false;return;}window.scrollTo(0,0);
