 $('#staff-month').value=today().slice(0,7);$('#staff-month').onchange=()=>loadStaff();const changeReference=()=>{const next=month();if(next===lastRequestedMonth)return;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(next)){++requestCounter;lastRequestedMonth='';$('#dash-body').innerHTML=empty('Selecione um mês válido.');return;}loadDashboard();};$('#month').oninput=changeReference;$('#month').onchange=changeReference;$('#refresh-admin').onclick=()=>loadDashboard(true);$('#refresh-staff').onclick=()=>loadStaff(true);
 $$('[data-tab]').forEach(b=>b.onclick=()=>{currentTab=b.dataset.tab;renderDashboard();});
 $$('[data-staff-tab]').forEach(b=>b.onclick=()=>{currentStaffTab=b.dataset.staffTab;renderStaff();b.scrollIntoView({block:'nearest',inline:'center'});const top=$('#staff-area .staff-main').getBoundingClientRect().top+scrollY-($('.staff-sidebar nav').offsetHeight||0);if(scrollY>top)scrollTo({top,behavior:'instant'});});
 const credentialsLogin=async(e,errorId)=>{e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]'),f=new FormData(form);button.disabled=true;$('#'+errorId).textContent='';try{const result=await api('staff/login',{username:f.get('username'),password:f.get('password')});form.reset();const destination=result.role==='owner'?'#gestao':'#barbeiro';if(location.hash===destination)route();else location.hash=destination;}catch(err){$('#'+errorId).textContent=err.message;}finally{button.disabled=false;}};
